# 案例 04：分组平均值统计

这是一个面向测试组织者的固定销售数据案例。输入包含 60,000 条逻辑记录和 12 个有效区域，混有缺失或无效收入、零值、负值、首尾空白、空区域，以及在备注中出现逗号、引号和嵌入换行的记录。数据由固定规则生成并保持确定性。

被测者只应收到 `TASK.md` 所描述的任务。仓库初始状态不包含统计结果。

验收脚本位于 `.benchmark/verify.py`。它会独立读取全部逻辑记录，以十进制定点语义计算分组结果，并严格核对输出字段、区域集合、排序、计数、两位小数格式和舍入结果。验收成功时退出码为 0，失败时退出码为非 0；本文档不记录各区域的实际答案。
---verify---
#!/usr/bin/env python3
"""Strict verifier for case 04."""

from __future__ import annotations

import csv
import hashlib
import re
import sys
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
INPUT = ROOT / "sales.csv"
OUTPUT = ROOT / "region_averages.csv"
MONEY_RE = re.compile(r"^-?(?:0|[1-9]\d*)\.\d{2}$")
COUNT_RE = re.compile(r"^(?:0|[1-9]\d*)$")
INPUT_SHA256 = "cfc68d766ce78df9ed1660ccbd842dcab382464f62c43f24a2a73490abc9a20e"


def fail(message: str) -> None:
    print(f"FAIL: {message}", file=sys.stderr)
    raise SystemExit(1)


def bytewise(values: list[str]) -> list[str]:
    return sorted(values, key=lambda value: value.encode("utf-8"))


def main() -> None:
    if not INPUT.is_file():
        fail("benchmark input is missing")
    if hashlib.sha256(INPUT.read_bytes()).hexdigest() != INPUT_SHA256:
        fail("sales.csv was modified")

    totals: dict[str, Decimal] = {}
    counts: dict[str, int] = {}
    try:
        with INPUT.open("r", encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames is None or "region" not in reader.fieldnames or "revenue" not in reader.fieldnames:
                fail("benchmark input has an invalid header")
            for row in reader:
                region = row.get("region")
                raw_revenue = row.get("revenue")
                if region is None or raw_revenue is None or region == "":
                    continue
                cleaned = raw_revenue.strip()
                if not cleaned:
                    continue
                try:
                    revenue = Decimal(cleaned)
                except InvalidOperation:
                    continue
                if not revenue.is_finite():
                    continue
                totals[region] = totals.get(region, Decimal("0")) + revenue
                counts[region] = counts.get(region, 0) + 1
    except (OSError, csv.Error) as exc:
        fail(f"cannot read benchmark input: {exc}")

    expected: dict[str, tuple[str, int]] = {}
    for region, total in totals.items():
        average = (total / counts[region]).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        expected[region] = (f"{average:.2f}", counts[region])

    if not OUTPUT.is_file():
        fail("region_averages.csv does not exist")

    try:
        with OUTPUT.open("r", encoding="utf-8", newline="") as handle:
            rows = list(csv.reader(handle))
    except (OSError, UnicodeDecodeError, csv.Error) as exc:
        fail(f"cannot read region_averages.csv: {exc}")

    if not rows or rows[0] != ["region", "average_revenue", "record_count"]:
        fail("output header is incorrect")
    data_rows = rows[1:]
    if any(len(row) != 3 for row in data_rows):
        fail("every output record must contain exactly three fields")
    regions = [row[0] for row in data_rows]
    if not regions or any(region == "" for region in regions):
        fail("output contains no regions or an empty region")
    if len(regions) != len(set(regions)):
        fail("output contains duplicate regions")
    if regions != bytewise(regions):
        fail("output regions are not sorted by UTF-8 byte order")
    if set(regions) != set(expected):
        fail("output region set is incorrect")

    for region, average_text, count_text in data_rows:
        if MONEY_RE.fullmatch(average_text) is None:
            fail(f"average_revenue has an invalid format for region {region!r}")
        if COUNT_RE.fullmatch(count_text) is None:
            fail(f"record_count has an invalid format for region {region!r}")
        expected_average, expected_count = expected[region]
        if average_text != expected_average:
            fail(f"average_revenue is incorrect for region {region!r}")
        if int(count_text) != expected_count:
            fail(f"record_count is incorrect for region {region!r}")

    print("PASS: region averages satisfy all requirements")


if __name__ == "__main__":
    main()
